import{I as t,o as p,c as o,b6 as e,J as r,w as d,j as i,a as l}from"./chunks/framework.BUXTSoD9.js";const g=JSON.parse('{"title":"Double Diamond: 올바른 일을 먼저 하고, 그 일을 제대로 하기","description":"제로 베이스 독자를 위한 Double Diamond 입문 글입니다. Discover, Define, Develop, Deliver 네 단계를 이해하고, 문제가 명확해지기 전에 서둘러 프로토타입을 만드는 일을 피합니다.","frontmatter":{"title":"Double Diamond: 올바른 일을 먼저 하고, 그 일을 제대로 하기","description":"제로 베이스 독자를 위한 Double Diamond 입문 글입니다. Discover, Define, Develop, Deliver 네 단계를 이해하고, 문제가 명확해지기 전에 서둘러 프로토타입을 만드는 일을 피합니다."},"headers":[],"relativePath":"ko-kr/stage-1/appendix-double-diamond/index.md","filePath":"ko-kr/stage-1/appendix-double-diamond/index.md"}'),h={name:"ko-kr/stage-1/appendix-double-diamond/index.md"},D=Object.assign(h,{setup(c){const s="약 <strong>1.5시간</strong>";return(u,a)=>{const n=t("ChapterIntroduction");return p(),o("div",null,[a[1]||(a[1]=e('<h1 id="double-diamond-올바른-일을-먼저-하고-그-일을-제대로-하기" tabindex="-1">Double Diamond: 올바른 일을 먼저 하고, 그 일을 제대로 하기 <a class="header-anchor" href="#double-diamond-올바른-일을-먼저-하고-그-일을-제대로-하기" aria-label="Permalink to “Double Diamond: 올바른 일을 먼저 하고, 그 일을 제대로 하기”">​</a></h1><p><a id="top-dd"></a></p><h2 id="이-장의-가이드" tabindex="-1">이 장의 가이드 <a class="header-anchor" href="#이-장의-가이드" aria-label="Permalink to “이 장의 가이드”">​</a></h2>',3)),r(n,{duration:s,tags:["Double Diamond","디자인 사고","요구사항 분석","솔루션 설계"],coreOutput:"더 명확한 문제 정의 1개와 더 합리적인 검증 진입점 1개",expectedOutput:"처음부터 서둘러 프로토타입을 그리지 않고, 먼저 문제를 명확히 생각한 후 솔루션을 비교하게 됩니다"},{default:d(()=>[...a[0]||(a[0]=[i("p",null,'많은 사람이 처음 제품을 만들 때 가장 많이 빠지는 함정은 "노력이 부족해서"가 아니라 너무 빨리 솔루션에 들어간다는 것입니다.',-1),i("p",null,"머릿속에 방향이 떠오르자마자, 페이지를 어떻게 그릴지, 버튼을 어디에 둘지, AI를 연동할지 말지, 로그인/회원가입을 만들지 말지, 프로토타입은 어떤 도구로 그릴지 생각하기 시작합니다. 한참을 바쁘게 돌아간 후에야, 가장 근본적인 문제를 전혀 생각하지 않았다는 것을 깨닫습니다: 사용자가 정말로 이 페인포인트를 가지고 있는지? 이 문제가 지금 해결할 가치가 있는지? 프로젝트를 진행하고 있다고 생각했지만, 사실은 잘못된 방향에서 열심히 가속하고 있었을 뿐입니다.",-1),i("p",null,"Double Diamond(더블 다이아몬드) 모델은 바로 이런 상황을 피하기 위한 것입니다.",-1),i("p",null,[l("이것이 가장 가치 있는 교훈은: "),i("strong",null,'"올바른 일을 하는 것"과 "일을 올바르게 하는 것"은 완전히 다른 단계라는 것입니다.'),l(" 문제를 아직 명확히 파악하지 못한 상태에서 서둘러 프로토타입을 만들면, 보통 잘못된 방향을 더 완성도 있게 만들 뿐입니다.")],-1)])]),_:1}),a[2]||(a[2]=e(`<div class="info custom-block"><p class="custom-block-title">최소 SOP</p><p><strong>목적</strong>: 이 글을 읽은 후, 제품을 만들 때 언제 먼저 문제를 생각해야 하고, 언제 솔루션과 프로토타입을 생각하기 시작해야 하는지 더 명확해져서, 처음부터 잘못된 방향에서 열심히 하는 일을 피할 수 있습니다.</p><p><strong>실행 항목</strong>: <code>Discover -&gt; Define -&gt; Develop -&gt; Deliver</code> 4단계로 진행하며, 각 단계에서 현재 단계에 해야 할 일만 합니다.</p><p><strong>결과</strong>: 더 명확한 문제 정의, 비교 가능한 여러 솔루션, 그리고 검증 가능한 최소 버전을 얻게 됩니다.</p><p><strong>키워드 바로가기</strong>: <a href="#dd-what">Double Diamond란</a> · <a href="#dd-first">첫 번째 다이아몬드</a> · <a href="#dd-ai">AI가 도와주는 방법</a></p></div><h2 id="배울-내용" tabindex="-1">배울 내용 <a class="header-anchor" href="#배울-내용" aria-label="Permalink to “배울 내용”">​</a></h2><ol><li>Double Diamond 모델이란 무엇이며, 왜 제로 베이스 제품 개발에 적합한지</li><li>Discover, Define, Develop, Deliver 네 단계에서 각각 무엇을 하는지</li><li>&quot;지금 계속 발산해야 하는지&quot;와 &quot;지금 수렴을 시작해야 하는지&quot;를 어떻게 구분하는지</li><li>Double Diamond 모델을 AI 제품, 프로토타입 설계, 요구사항 검증에 어떻게 적용하는지</li></ol><p><a id="dd-what"></a></p><h2 id="_1-double-diamond-모델이란-무엇인가" tabindex="-1"><a href="#top-dd">1. Double Diamond 모델이란 무엇인가</a> <a class="header-anchor" href="#_1-double-diamond-모델이란-무엇인가" aria-label="Permalink to “1. Double Diamond 모델이란 무엇인가”">​</a></h2><p>Double Diamond 모델은 영국 <strong>Design Council</strong>이 보급한 고전적인 디자인 프로세스 프레임워크입니다. 완전한 디자인과 혁신 과정을 두 개의 연속된 다이아몬드 모양으로 표현합니다.</p><p>&quot;다이아몬드&quot;인 이유는, 각 다이아몬드가 서로 반대되지만 모두 중요한 두 가지 동작을 포함하기 때문입니다:</p><ul><li><strong>발산</strong>: 먼저 시야를 넓혀 더 많은 가능성을 봅니다</li><li><strong>수렴</strong>: 그런 다음 범위를 좁혀 판단하고 선택합니다</li></ul><p>전체 과정은 총 4단계입니다:</p><ol><li><strong>Discover</strong>: 사용자, 문제, 환경, 시장을 폭넓게 이해</li><li><strong>Define</strong>: 대량의 정보에서 정말로 해결할 가치가 있는 핵심 문제를 추출</li><li><strong>Develop</strong>: 핵심 문제를 중심으로 다양한 솔루션을 발산</li><li><strong>Deliver</strong>: 선별, 프로토타입, 테스트 및 더 적합한 솔루션 전달</li></ol><p>이 네 단계를 가장 기억하기 쉬운 한 문장으로 압축하면:</p><ul><li><strong>첫 번째 다이아몬드</strong>: 먼저 무엇을 해결해야 하는지 명확히 파악하기</li><li><strong>두 번째 다이아몬드</strong>: 그 문제를 어떤 솔루션으로 해결할지 결정하기</li></ul><p>이것은 아까 정확하게 말씀하신 그 문장이기도 합니다:</p><ul><li><strong>첫 번째 다이아몬드: 올바른 일을 하기</strong></li><li><strong>두 번째 다이아몬드: 일을 올바르게 하기</strong></li></ul><h2 id="_2-왜-double-diamond-모델이-특히-초보자에게-적합한가" tabindex="-1">2. 왜 Double Diamond 모델이 특히 초보자에게 적합한가 <a class="header-anchor" href="#_2-왜-double-diamond-모델이-특히-초보자에게-적합한가" aria-label="Permalink to “2. 왜 Double Diamond 모델이 특히 초보자에게 적합한가”">​</a></h2><p>초보자가 제품을 만들 때 가장 흔한 리듬은 보통 이렇습니다:</p><ul><li>아이디어가 하나 떠오름</li><li>이 방향이 멋지다고 느낌</li><li>바로 프로토타입을 그리기 시작함</li><li>하다 보니 기능이 점점 많아짐</li><li>결국 자신이 무슨 문제를 해결하고 있는지 모르게 됨</li></ul><p>Double Diamond 모델의 가치는 프로세스를 복잡하게 만드는 것이 아니라, <strong>&quot;문제 이해&quot;와 &quot;솔루션 설계&quot;를 분리하도록 강제</strong>하는 데 있습니다.</p><p>이것은 평범하게 들리지만, 실제로는 매우 중요합니다. 왜냐하면 많은 실패한 제품이 실행이 성실하지 않아서가 아니라:</p><ul><li>잘못된 문제를 선택했기 때문</li><li>사용자를 오해했기 때문</li><li>너무 일찍 솔루션에 고정되었기 때문</li><li>방향을 검증하지 않고 세부 사항을 다듬는 데 많은 시간을 썼기 때문</li></ul><p>Double Diamond 모델은 계속해서 다음을 상기시킵니다:</p><ul><li>아이디어가 편해서 문제가 이미 성립했다고 가정하지 마세요</li><li>솔루션을 만들 수 있다고 해서 그것이 가치 있다고 가정하지 마세요</li><li>프로토타입이 완성되어 보인다고 해서 사용자가 정말로 필요로 할 것이라고 가정하지 마세요</li></ul><p><a id="dd-first"></a></p><h2 id="_3-첫-번째-다이아몬드-올바른-일을-하기" tabindex="-1"><a href="#top-dd">3. 첫 번째 다이아몬드: 올바른 일을 하기</a> <a class="header-anchor" href="#_3-첫-번째-다이아몬드-올바른-일을-하기" aria-label="Permalink to “3. 첫 번째 다이아몬드: 올바른 일을 하기”">​</a></h2><p>첫 번째 다이아몬드가 주목하는 것은 <strong>문제 자체</strong>이며, 솔루션이 아닙니다.</p><p>한 문장으로 이해하자면: <strong>서둘러 하지 말고, 먼저 할 가치가 있는지 확인하세요.</strong></p><h3 id="_3-1-discover-먼저-문제-공간을-열기" tabindex="-1">3.1 Discover: 먼저 문제 공간을 열기 <a class="header-anchor" href="#_3-1-discover-먼저-문제-공간을-열기" aria-label="Permalink to “3.1 Discover: 먼저 문제 공간을 열기”">​</a></h3><p>Discover 단계의 핵심 작업은 <strong>폭넓은 조사이며, 빠른 결론을 내리는 것이 아닙니다.</strong></p><p>이 단계에서 보통 하는 일은:</p><ul><li>사용자가 실제 시나리오에서 어떻게 행동하는지 관찰</li><li>잠재 사용자를 인터뷰하여, 최근에 문제를 만난 것이 언제였는지 파악</li><li>현재 어떻게 대충 해결하는지 관찰</li><li>경쟁 제품과 대체 솔루션이 어떻게 처리하는지 확인</li><li>시장, 프로세스, 제약 조건, 업스트림/다운스트림 정보 수집</li></ul><p>많은 사람이 Discover를 &quot;자료를 많이 보는 것&quot;으로 오해합니다. 사실 더 중요한 것은: <strong>정보를 한 무더기 검색하는 것이 아니라, 사람과 시나리오를 이해하는 것입니다.</strong></p><p>예를 들어 &quot;AI로 회의록 정리 도구&quot;를 만들고 싶다면, Discover 단계에서 더 주목해야 할 것은:</p><ul><li>사용자가 회의 후 어디서 가장 고통스러워하는지</li><li>기록이 어려운지, 정리가 어려운지, 아니면 공유가 어려운지</li><li>현재 직접 작성하는지, 인턴에게 맡기는지, 녹음을 다시 듣는지, 아니면 아예 정리하지 않는지</li><li>어떤 회의 시나리오에서 회의록이 가장 필요한지, 어떤 시나리오에서는 전혀 필요 없는지</li></ul><p>이 단계의 가장 중요한 목표는 답을 얻는 것이 아니라, <strong>너무 일찍 답을 알고 있다고 생각하지 않는 것입니다.</strong></p><h3 id="_3-2-define-정보-더미에서-핵심-문제-추출" tabindex="-1">3.2 Define: 정보 더미에서 핵심 문제 추출 <a class="header-anchor" href="#_3-2-define-정보-더미에서-핵심-문제-추출" aria-label="Permalink to “3.2 Define: 정보 더미에서 핵심 문제 추출”">​</a></h3><p>Discover가 시야를 넓히는 것이라면, Define은 수렴을 시작하는 것입니다.</p><p>Define 단계에서 해야 할 것은 모든 관찰을 보존하는 것이 아니라, 다음을 묻는 것입니다:</p><ul><li>정말로 우선적으로 해결할 가치가 있는 문제는 무엇인가</li><li>어떤 문제가 가장 자주 나타나고, 가장 아프고, 가장 가치가 있는가</li><li>우리 첫 번째 버전은 어떤 시나리오에만 집중할 것인가</li></ul><p>이 단계의 핵심은 넓은 주제를 명확한 문제 정의로 수렴하는 것입니다.</p><p>예를 들어 처음에 이렇게 말했다면:</p><blockquote><p>회의 효율을 높이는 AI 도구를 만들고 싶습니다.</p></blockquote><p>Define 단계에 이르면, 더 나은 표현은 이렇게 될 수 있습니다:</p><blockquote><p>프로젝트형 팀이 30~60분 협업 회의가 끝난 후, 10분 이내에 할 일, 담당자, 마감일이 포함된 회의록을 출력하지 못하는 문제를 먼저 해결하겠습니다.</p></blockquote><p>이때 문제가 명확해지기 시작합니다:</p><ul><li>사용자가 누구인지</li><li>시나리오가 무엇인지</li><li>막힌 곳이 어디인지</li><li>성공 기준이 무엇인지</li></ul><p>Define의 본질은 <strong>&quot;문제가 많다&quot;에서 &quot;이번에 어떤 문제를 먼저 해결할 것인가&quot;로 수렴하는 것입니다.</strong></p><h2 id="_4-두-번째-다이아몬드-일을-올바르게-하기" tabindex="-1">4. 두 번째 다이아몬드: 일을 올바르게 하기 <a class="header-anchor" href="#_4-두-번째-다이아몬드-일을-올바르게-하기" aria-label="Permalink to “4. 두 번째 다이아몬드: 일을 올바르게 하기”">​</a></h2><p>첫 번째 다이아몬드를 완료한 후에야 비로소 두 번째 다이아몬드에 진입하는 것이 적절합니다. 왜냐하면 이때 해결하는 것은 모호한 방향이 아니라, 수렴된 구체적인 문제이기 때문입니다.</p><h3 id="_4-1-develop-핵심-문제를-중심으로-솔루션-발산" tabindex="-1">4.1 Develop: 핵심 문제를 중심으로 솔루션 발산 <a class="header-anchor" href="#_4-1-develop-핵심-문제를-중심으로-솔루션-발산" aria-label="Permalink to “4.1 Develop: 핵심 문제를 중심으로 솔루션 발산”">​</a></h3><p>Develop 단계의 핵심은 <strong>같은 문제를 중심으로 여러 가능한 솔루션을 탐색하는 것입니다.</strong></p><p>주의할 점은, 여기서의 발산은 Discover 단계의 발산과 다릅니다.</p><ul><li>Discover의 발산은 문제 공간을 탐색하는 것</li><li>Develop의 발산은 솔루션 공간을 탐색하는 것</li></ul><p>회의록 예시를 계속하면, Develop 단계에서는 이런 것들을 생각할 수 있습니다:</p><ul><li>웹 도구로 할지, 회의 플러그인으로 할지</li><li>녹음을 업로드한 후 처리할지, 실시간 기록으로 할지</li><li>요약만 할지, 할 일 추출을 중심으로 할지</li><li>개인 효율을 강조할지, 팀 동기화를 강조할지</li><li>사용자에게 자유로운 편집을 제공할지, 구조화된 템플릿을 직접 출력할지</li></ul><p>이 단계는 브레인스토밍에 매우 적합하며, 팀과 함께 솔루션을 펼쳐보는 데도 좋습니다.</p><p>하지만 여기에는 전제가 있습니다: <strong>모든 솔루션은 동일하게 정의된 문제에 봉사해야 합니다.</strong> 문제가 명확하게 정의되지 않으면, Develop은 쉽게 다시 기능이 난무하는 상황이 됩니다.</p><h3 id="_4-2-deliver-솔루션-선택-프로토타입-테스트-및-전달" tabindex="-1">4.2 Deliver: 솔루션 선택, 프로토타입, 테스트 및 전달 <a class="header-anchor" href="#_4-2-deliver-솔루션-선택-프로토타입-테스트-및-전달" aria-label="Permalink to “4.2 Deliver: 솔루션 선택, 프로토타입, 테스트 및 전달”">​</a></h3><p>Deliver 단계는 두 번째 다이아몬드의 수렴 단계입니다.</p><p>이때 해야 할 것은 계속 더 많은 것을 생각하는 것이 아니라, 판단을 시작하는 것입니다:</p><ul><li>현재 단계에 가장 적합한 솔루션은 무엇인가</li><li>가장 작지만 가장 유용한 버전은 무엇인가</li><li>어떤 기능을 먼저 해야 하고, 어떤 것은 나중에 해도 되는가</li><li>프로토타입, 테스트, 소규모 검증은 어떻게 할 것인가</li></ul><p>많은 사람이 Deliver를 &quot;출시&quot;와 같다고 생각합니다. 사실 더 정확한 의미는: <strong>솔루션을 테스트 가능하고, 검증 가능하고, 반복 가능한 것으로 만드는 것입니다.</strong></p><p>그것은 다음과 같을 수 있습니다:</p><ul><li>저해상도 흐름도</li><li>Figma 프로토타입</li><li>실행 가능한 MVP</li><li>소규모 사용자 테스트</li><li>실제 피드백 후 반복 버전</li></ul><p>Deliver의 핵심은 &quot;완벽한 전달&quot;이 아니라, <strong>최대한 빨리 솔루션을 실제 환경에서 검증하는 것입니다.</strong></p><h2 id="_5-가장-기억하기-쉬운-비교표" tabindex="-1">5. 가장 기억하기 쉬운 비교표 <a class="header-anchor" href="#_5-가장-기억하기-쉬운-비교표" aria-label="Permalink to “5. 가장 기억하기 쉬운 비교표”">​</a></h2><p>네 단계를 항상 헷갈린다면, 아래 버전을 바로 기억하세요:</p><table tabindex="0"><thead><tr><th>단계</th><th>하는 일</th><th>키워드</th><th>일반적 산출물</th></tr></thead><tbody><tr><td>Discover</td><td>문제 이해</td><td>조사, 관찰, 인터뷰, 정보 수집</td><td>사용자 인사이트, 시나리오 노트, 문제 목록</td></tr><tr><td>Define</td><td>문제 정의</td><td>추출, 집중, 선택, 문제 재작성</td><td>문제 정의, 우선순위, MVP 진입점</td></tr><tr><td>Develop</td><td>솔루션 탐색</td><td>브레인스토밍, 비교, 공동 창작, 프로토타입 구상</td><td>솔루션 목록, 흐름 스케치, 프로토타입 방향</td></tr><tr><td>Deliver</td><td>솔루션 검증</td><td>프로토타입, 테스트, 반복, 전달</td><td>프로토타입, 테스트 피드백, 최적화 버전</td></tr></tbody></table><p>더 압축하면 이렇습니다:</p><ul><li><strong>Discover / Define</strong>: &quot;올바른 일을 하기&quot; 해결</li><li><strong>Develop / Deliver</strong>: &quot;일을 올바르게 하기&quot; 해결</li></ul><h2 id="_6-double-diamond-모델의-가장-흔한-오해" tabindex="-1">6. Double Diamond 모델의 가장 흔한 오해 <a class="header-anchor" href="#_6-double-diamond-모델의-가장-흔한-오해" aria-label="Permalink to “6. Double Diamond 모델의 가장 흔한 오해”">​</a></h2><h3 id="_6-1-discover도-안-했는데-바로-deliver" tabindex="-1">6.1 Discover도 안 했는데 바로 Deliver <a class="header-anchor" href="#_6-1-discover도-안-했는데-바로-deliver" aria-label="Permalink to “6.1 Discover도 안 했는데 바로 Deliver”">​</a></h3><p>이것이 가장 흔한 경우입니다. 많은 사람이 아이디어가 떠오르자마자 프로토타입을 그리고, PRD를 쓰고, 모델을 연동하고, 페이지를 만듭니다.</p><p>문제는 성실하지 않다는 것이 아니라, 문제가 해결할 가치가 있는지 확인조차 하지 않았을 수 있다는 것입니다.</p><h3 id="_6-2-discover을-오래-하지만-define을-계속하지-않음" tabindex="-1">6.2 Discover을 오래 하지만, Define을 계속하지 않음 <a class="header-anchor" href="#_6-2-discover을-오래-하지만-define을-계속하지-않음" aria-label="Permalink to “6.2 Discover을 오래 하지만, Define을 계속하지 않음”">​</a></h3><p>또 다른 극단은 계속 조사하고, 계속 자료를 보고, 계속 인터뷰하지만, 수렴하지 못하는 것입니다.</p><p>Double Diamond는 무한한 발산을 요구하는 것이 아니라, 발산 후에는 반드시 판단과 선택으로 진입해야 한다는 것을 상기시킵니다.</p><h3 id="_6-3-define-후-몰래-문제를-바꿈" tabindex="-1">6.3 Define 후, 몰래 문제를 바꿈 <a class="header-anchor" href="#_6-3-define-후-몰래-문제를-바꿈" aria-label="Permalink to “6.3 Define 후, 몰래 문제를 바꿈”">​</a></h3><p>많은 팀이 Develop 단계에서 어떤 솔루션이 더 쉽게 만들 수 있다는 이유로, 문제 정의를 역으로 수정하여 기존 솔루션에 맞춥니다.</p><p>이것은 위험합니다. 왜냐하면 문제를 해결하는 것이 아니라, 자신이 좋아하는 솔루션을 위해 이유를 찾고 있을 수 있기 때문입니다.</p><h3 id="_6-4-deliver을-크고-완전한-출시-로-오해" tabindex="-1">6.4 Deliver을 &quot;크고 완전한 출시&quot;로 오해 <a class="header-anchor" href="#_6-4-deliver을-크고-완전한-출시-로-오해" aria-label="Permalink to “6.4 Deliver을 &quot;크고 완전한 출시&quot;로 오해”">​</a></h3><p>Deliver이 반드시 완전한 제품을 모두 완성해야 끝나는 것은 아닙니다. 많은 경우, 테스트 가능한 프로토타입이나 한 차례의 실제 사용자 테스트만으로도 이미 훌륭한 deliver입니다.</p><h2 id="_7-ai-제품에서-double-diamond-모델을-어떻게-사용할까" tabindex="-1">7. AI 제품에서 Double Diamond 모델을 어떻게 사용할까 <a class="header-anchor" href="#_7-ai-제품에서-double-diamond-모델을-어떻게-사용할까" aria-label="Permalink to “7. AI 제품에서 Double Diamond 모델을 어떻게 사용할까”">​</a></h2><p>AI 제품은 특히 &quot;기능 우선&quot; 함정에 빠지기 쉽습니다. 왜냐하면 모델의 능력이 너무 매력적으로 보이기 때문입니다. 바로 이런 것들을 생각하고 싶어집니다:</p><ul><li>멀티모달을 연동할지 말지</li><li>Agent를 만들지 말지</li><li>워크플로를 추가할지 말지</li><li>음성, 이미지, 인터넷 검색을 연동할지 말지</li></ul><p>하지만 Double Diamond 모델은 먼저 이것을 묻도록 합니다:</p><ul><li>사용자가 정확히 어느 단계에서 막혀 있는지</li><li>이 막힌 곳이 반드시 AI가 필요한 것인지</li><li>AI를 사용하지 않는다면, 기존 방법이 정확히 어디서 가장 나쁜지</li><li>AI를 넣은 후, 가장 핵심적인 진전은 무엇인지</li></ul><p>이것은 흔한 상황을 피하는 데 도움이 됩니다: <strong>능력은 강하지만, 가치는 약함.</strong></p><p>실용적인 순서는:</p><ol><li>Discover 단계에서 사용자가 현재 작업을 어떻게 처리하는지 관찰</li><li>Define 단계에서 가장 아픈 시나리오를 명확한 문제 정의 한 문장으로 작성</li><li>Develop 단계에서 어떤 AI 능력이 이 문제에 가장 적합한지 비교</li><li>Deliver 단계에서 최소 버전을 만들어 실제 사용자에게 테스트</li></ol><h2 id="_8-바로-사용할-수-있는-double-diamond-템플릿" tabindex="-1">8. 바로 사용할 수 있는 Double Diamond 템플릿 <a class="header-anchor" href="#_8-바로-사용할-수-있는-double-diamond-템플릿" aria-label="Permalink to “8. 바로 사용할 수 있는 Double Diamond 템플릿”">​</a></h2><p>자신의 제품을 만들고 있다면, 다음 순서대로 작성해 보세요:</p><h3 id="discover" tabindex="-1">Discover <a class="header-anchor" href="#discover" aria-label="Permalink to “Discover”">​</a></h3><ul><li>내가 관찰한 사용자는 누구인가?</li><li>그들이 최근에 이 문제를 만난 것은 언제인가?</li><li>지금 어떻게 해결하고 있는가?</li><li>가장 번거롭고, 가장 느리고, 가장 불안한 부분은 무엇인가?</li></ul><h3 id="define" tabindex="-1">Define <a class="header-anchor" href="#define" aria-label="Permalink to “Define”">​</a></h3><ul><li>이 문제들 중, 가장 먼저 해결할 가치가 있는 것은 무엇인가?</li><li>어떤 시나리오가 가장 빈도가 높거나, 가장 핵심적인가?</li><li>첫 번째 버전에서는 누구만 서비스하고, 무엇만 해결할 것인가?</li><li>성공적으로 해결된 후, 사용자의 상태는 어떻게 변할 것인가?</li></ul><h3 id="develop" tabindex="-1">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to “Develop”">​</a></h3><ul><li>이 문제에 대해, 어떤 가능한 솔루션이 있는가?</li><li>어떤 솔루션이 가장 가볍고, 가장 빠르고, 가장 검증하기 쉬운가?</li><li>반드시 해야 할 것은 무엇이고, 나중에 해도 되는 것은 무엇인가?</li></ul><h3 id="deliver" tabindex="-1">Deliver <a class="header-anchor" href="#deliver" aria-label="Permalink to “Deliver”">​</a></h3><ul><li>이 방향을 검증하기 위해 최소한 무엇을 전달할 수 있는가?</li><li>흐름도인가, 프로토타입인가, MVP인가?</li><li>누구에게 테스트를 맡겨야 하는가?</li><li>테스트 후 계속할지, 수정할지, 포기할지 어떻게 판단할 것인가?</li></ul><h2 id="_9-제로-베이스도-이해할-수-있는-예시" tabindex="-1">9. 제로 베이스도 이해할 수 있는 예시 <a class="header-anchor" href="#_9-제로-베이스도-이해할-수-있는-예시" aria-label="Permalink to “9. 제로 베이스도 이해할 수 있는 예시”">​</a></h2><p>&quot;대학생의 구직 이력서를 준비해 주는&quot; AI 도구를 만들고 싶다고 가정해 봅시다.</p><p>많은 사람이 처음부터 두 번째 다이아몬드에 진입하여 이런 것들을 생각합니다:</p><ul><li>원클릭 미화를 할지 말지</li><li>지능형 재작성을 할지 말지</li><li>자동 JD 매칭을 할지 말지</li><li>자기소개서를 생성할지 말지</li></ul><p>하지만 Double Diamond 모델에 따르면, 더 나은 과정은 이렇습니다:</p><h3 id="첫-번째-다이아몬드" tabindex="-1">첫 번째 다이아몬드 <a class="header-anchor" href="#첫-번째-다이아몬드" aria-label="Permalink to “첫 번째 다이아몬드”">​</a></h3><p><strong>Discover</strong></p><ul><li>최근 졸업생에게 마지막으로 이력서를 수정한 것이 언제였는지 물어보기</li><li>그들이 기존 이력서에서 새 버전으로 어떻게 수정하는지 보기</li><li>가장 고민인 것이 &quot;작성 방법을 모름&quot;, &quot;수정 방법을 모름&quot;, &quot;좋은지 판단 방법을 모름&quot; 중 어느 것인지 파악</li></ul><p><strong>Define</strong></p><ul><li>마지막으로 더 구체적인 문제로 수렴:</li><li>&quot;대학생이 이력서를 못 만드는 것이 아니라&quot;</li><li>&quot;처음으로 인턴십에 지원하는 학생이 기존 경험을 공고에 맞는 표현으로 재작성하기 어려워, 지원을 미루는 것&quot;</li></ul><h3 id="두-번째-다이아몬드" tabindex="-1">두 번째 다이아몬드 <a class="header-anchor" href="#두-번째-다이아몬드" aria-label="Permalink to “두 번째 다이아몬드”">​</a></h3><p><strong>Develop</strong></p><ul><li>여러 솔루션 생각: 템플릿 라이브러리, AI 재작성, 공고 대조, 이력서 평가, 사례 참고</li></ul><p><strong>Deliver</strong></p><ul><li>첫 번째 버전은 &quot;공고 설명에 따라 경험 bullet points를 재작성&quot;만 하기</li><li>5명의 학생에게 사용해 보고, 더 빨리 첫 번째 버전의 이력서를 제출하는지 확인</li></ul><p>첫 번째 다이아몬드를 탄탄하게 하면, 두 번째 다이아몬드가 훨씬 명확해지는 것을 발견할 것입니다.</p><h2 id="_10-요약" tabindex="-1">10. 요약 <a class="header-anchor" href="#_10-요약" aria-label="Permalink to “10. 요약”">​</a></h2><p>Double Diamond 모델의 가장 강력한 점은, 한 무더기의 혼란을 네 개의 더 명확한 동작으로 나누어 준다는 것입니다:</p><ul><li>먼저 발산하여 문제를 이해</li><li>다시 수렴하여 문제를 정의</li><li>다시 발산하여 솔루션을 탐색</li><li>마지막으로 수렴하여 솔루션을 전달</li></ul><p>이것은 여러분을 느리게 만드는 것이 아니라, <strong>바쁘게 보이지만 실제로 방향이 잘못된 많은 우회를 덜 하게 해줍니다.</strong></p><p>특히 AI 시대에는 것을 만드는 것이 점점 빨라지고 있어, Double Diamond 모델이 오히려 더 중요해집니다. 왜냐하면 &quot;만들어 내는 것&quot;이 점점 쉬워질수록, 진정으로 희귀한 능력은 다음이 되기 때문입니다: <strong>해결할 가치가 있는 문제를 해결하고 있는지, 그리고 적절한 방식으로 해결하고 있는지.</strong></p><p>이 한 문장만 기억하면 됩니다:</p><p><strong>먼저 올바른 일을 하고, 그 다음에 일을 올바르게 하세요.</strong></p><p><a id="dd-ai"></a></p><h2 id="_11-ai를-활용해-double-diamond-프로세스를-실행하는-방법" tabindex="-1"><a href="#top-dd">11. AI를 활용해 Double Diamond 프로세스를 실행하는 방법</a> <a class="header-anchor" href="#_11-ai를-활용해-double-diamond-프로세스를-실행하는-방법" aria-label="Permalink to “11. AI를 활용해 Double Diamond 프로세스를 실행하는 방법”">​</a></h2><p>Double Diamond 모델 자체는 AI 도구가 아니지만, AI는 네 단계에서 &quot;가속기&quot; 역할을 하기에 매우 적합합니다. 핵심은 AI가 대신 결정하게 하는 것이 아니라, 시야를 넓히고, 정보를 정리하고, 솔루션을 비교하고, 검증 자료를 생성하는 것을 돕게 하는 것입니다.</p><h3 id="_11-1-discover-단계-ai로-먼저-정보-기반-마련" tabindex="-1">11.1 Discover 단계: AI로 먼저 정보 기반 마련 <a class="header-anchor" href="#_11-1-discover-단계-ai로-먼저-정보-기반-마련" aria-label="Permalink to “11.1 Discover 단계: AI로 먼저 정보 기반 마련”">​</a></h3><p>공식 인터뷰와 조사 전에 AI에게 가벼운 문제 스캔을 먼저 맡길 수 있습니다. 예를 들어:</p><ul><li>시장에서 흔한 대체 솔루션은 무엇인지</li><li>사용자가 공개 커뮤니티에서 가장 많이 불만을 제기하는 것이 무엇인지</li><li>이 문제가 어떤 시나리오와 사용자군에서 흔한지</li><li>기존 제품이 보통 무엇을 간과하는지</li></ul><p>이 단계는 실제 조사를 대체할 수 없지만, 빠르게 문제 지도를 구축하는 데 매우 적합합니다.</p><p>아주 간단한 초보자 입력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>대학생의 이력서를 수정하는 도구를 만들고 싶습니다.</span></span>
<span class="line"><span>먼저 기능을 생각하지 말고, 이 문제에서 사람들이 가장 많이 겪는 어려움이 무엇인지 먼저 봐 주세요.</span></span></code></pre></div><p>AI의 출력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>초기 문제 지도:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 어떤 경험을 써야 할지 모름</span></span>
<span class="line"><span>2. 공고에 맞게 어떻게 수정해야 할지 모름</span></span>
<span class="line"><span>3. 여러 번 수정해도 충분히 좋은지 확신이 안 됨</span></span>
<span class="line"><span>4. 다른 사람에게 검토를 부탁해야 하지만, 매번 부탁하기가 불편함</span></span>
<span class="line"><span>5. 확신이 없어서, 계속 지원을 미룸</span></span></code></pre></div><p>이런 출력의 역할은 대신 결론을 내리는 것이 아니라, 더 빨리 Discover에 진입하도록 돕는 것입니다.</p><h3 id="_11-2-define-단계-ai가-문제-정의를-수렴하도록-돕기" tabindex="-1">11.2 Define 단계: AI가 문제 정의를 수렴하도록 돕기 <a class="header-anchor" href="#_11-2-define-단계-ai가-문제-정의를-수렴하도록-돕기" aria-label="Permalink to “11.2 Define 단계: AI가 문제 정의를 수렴하도록 돕기”">​</a></h3><p>많은 사람이 자료를 많이 수집한 후, 가장 어려운 것은 문제를 정말로 명확한 한 문장으로 수렴하는 것입니다. 조사 노트를 AI에게 전달하여, 몇 가지 후보 문제 정의로 압축하도록 할 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>다음은 Discover 단계에서 수집한 사용자 피드백과 조사 노트입니다:</span></span>
<span class="line"><span>[내용 붙여넣기]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>세 가지 일을 해 주세요:</span></span>
<span class="line"><span>1. 가장 자주 나타나는 문제 패턴을 정리</span></span>
<span class="line"><span>2. 문제 빈도, 고통 정도, 검증 가능성에 따라, 우선적으로 해결할 가치가 있는 문제 3개를 정리</span></span>
<span class="line"><span>3. 각 문제를 구체적인 문제 정의 한 문장으로 작성</span></span></code></pre></div><p>이렇게 하면 &quot;문제가 많다&quot;는 상태에 머물지 않고 Define에 더 쉽게 진입할 수 있습니다.</p><p>입력을 아주 간단하게 쓸 수도 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>내가 지금 수집한 문제는 다음과 같습니다:</span></span>
<span class="line"><span>1. 다들 이력서에 뭘 써야 할지 모름</span></span>
<span class="line"><span>2. 다들 어떻게 수정해야 할지 모름</span></span>
<span class="line"><span>3. 다들 수정이 안 된 것 같아서, 지원을 못 함</span></span>
<span class="line"><span></span></span>
<span class="line"><span>첫 번째 버전에서 가장 먼저 해결할 문제가 무엇인지 봐 주세요.</span></span></code></pre></div><p>AI의 출력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>우선적으로 해결할 것을 권장하는 문제:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;처음으로 인턴십에 지원하는 학생이, 이력서가 이미 지원 가능한 수준에 도달했는지 확신하지 못해, 반복적으로 수정하며 지원을 미룸.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>이유:</span></span>
<span class="line"><span>1. 이 문제가 더 구체적임</span></span>
<span class="line"><span>2. 지연 행동을 설명할 수 있음</span></span>
<span class="line"><span>3. 작은 버전을 설계하여 검증하기 더 쉬움</span></span></code></pre></div><p>이런 출력은 매우 유용합니다. 왜냐하면 많은 모호한 문제에서 MVP 출발점에 더 가까운 정의를 수렴해 주기 때문입니다.</p><h3 id="_11-3-develop-단계-ai로-여러-솔루션-발산" tabindex="-1">11.3 Develop 단계: AI로 여러 솔루션 발산 <a class="header-anchor" href="#_11-3-develop-단계-ai로-여러-솔루션-발산" aria-label="Permalink to “11.3 Develop 단계: AI로 여러 솔루션 발산”">​</a></h3><p>많은 사람이 문제를 정의한 후, 머릿속에 가장 먼저 떠오른 솔루션만 바라봅니다. AI는 이 단계에서 강제 발산을 도와주기에 매우 적합합니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>핵심 문제를 정의했습니다: [문제 정의]</span></span>
<span class="line"><span>최종 답을 바로 주지 말고, 다음 관점에서 각각 2~3가지 해결 방향을 제시해 주세요:</span></span>
<span class="line"><span>1. 가장 가벼운 MVP</span></span>
<span class="line"><span>2. 수요를 검증하기에 가장 적합한 솔루션</span></span>
<span class="line"><span>3. 경험을 개선하는 데 가장 적합한 솔루션</span></span>
<span class="line"><span>4. AI에 의존하지 않는 솔루션</span></span>
<span class="line"><span>5. AI에 의존하는 솔루션</span></span>
<span class="line"><span>마지막으로 각 솔루션의 장점, 위험, 검증 비용을 비교해 주세요.</span></span></code></pre></div><p>이렇게 하면 너무 일찍 단일 솔루션에 갇히지 않습니다.</p><p>간단한 입력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>내 문제 정의는 다음과 같습니다:</span></span>
<span class="line"><span>&quot;대학생이 이력서가 이미 지원할 수 있는지 확신하지 못해, 계속 지원을 미룸.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4가지 다른 솔루션을 생각해 주세요. 한 가지만 주지 마세요.</span></span></code></pre></div><p>AI의 출력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>솔루션 1: 이력서 지원 가능 체크리스트</span></span>
<span class="line"><span>솔루션 2: 공고 설명에 따른 맞춤형 재작성</span></span>
<span class="line"><span>솔루션 3: 사용자가 이력서를 업로드하면 위험 신호를 제시</span></span>
<span class="line"><span>솔루션 4: 우수 사례 대조를 제공하여 사용자가 격차를 판단하도록 도움</span></span></code></pre></div><p>이때 &quot;솔루션 비교&quot;에 더 쉽게 진입할 수 있으며, 처음부터 AI 재작성이라는 한 방향만 바라보지 않게 됩니다.</p><h3 id="_11-4-deliver-단계-ai로-프로토타입-카피와-테스트-자료-생성" tabindex="-1">11.4 Deliver 단계: AI로 프로토타입 카피와 테스트 자료 생성 <a class="header-anchor" href="#_11-4-deliver-단계-ai로-프로토타입-카피와-테스트-자료-생성" aria-label="Permalink to “11.4 Deliver 단계: AI로 프로토타입 카피와 테스트 자료 생성”">​</a></h3><p>Deliver 단계에 진입하면, AI는 다음 작업을 가속화하는 데 매우 적합합니다:</p><ul><li>저해상도 프로토타입의 페이지 카피 생성</li><li>사용자 테스트 스크립트 정리</li><li>비교 가능한 여러 버전의 제목, 버튼, 설명어 생성</li><li>테스트 후 피드백과 문제 목록 정리</li></ul><p>예를 들어 AI에게 20분 사용자 테스트 스크립트를 생성하거나, 5명의 사용자 피드백을 &quot;계속 진행/방향 수정/일시 중지&quot;의 판단 근거로 정리하도록 할 수 있습니다.</p><p>최소 입력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>아주 간단한 프로토타입을 만들었어요:</span></span>
<span class="line"><span>사용자가 이력서를 업로드하면, 어느 부분이 아직 지원에 부적합한지 알려줘요.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>15분 사용자 테스트 스크립트를 생성해 주세요.</span></span></code></pre></div><p>AI의 출력은 다음과 같을 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>15분 테스트 스크립트:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 먼저 사용자에게 최근 이력서 제출 경험을 설명해 달라고 요청</span></span>
<span class="line"><span>2. 사용자가 독립적으로 이력서 업로드를 완료하게 함</span></span>
<span class="line"><span>3. 피드백 결과를 이해할 수 있는지 관찰</span></span>
<span class="line"><span>4. 질문: 이 안내 중 어떤 것이 가장 도움이 되었고, 어떤 것이 혼란스러웠는지</span></span>
<span class="line"><span>5. 질문: 다음에 제출하기 전에 다시 사용하고 싶은지</span></span></code></pre></div><p>이런 출력은 매우 실용적입니다. 왜냐하면 &quot;프로토타입을 완성했다&quot;에서 &quot;다음에 어떻게 테스트할지&quot;까지 나아갈 수 있게 해주기 때문입니다.</p><h3 id="_11-5-ai를-단계-수문원-으로-활용" tabindex="-1">11.5 AI를 &quot;단계 수문원&quot;으로 활용 <a class="header-anchor" href="#_11-5-ai를-단계-수문원-으로-활용" aria-label="Permalink to “11.5 AI를 &quot;단계 수문원&quot;으로 활용”">​</a></h3><p>Double Diamond 모델의 가장 흔한 문제는 단계를 건너뛰는 것입니다. AI에게 직접 수문원 역할을 맡겨, 지금 정확히 어느 단계에 있는지 상기시키도록 할 수 있습니다:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>제품 프로세스 코치 역할을 해 주세요.</span></span>
<span class="line"><span>다음은 내 현재 프로젝트 상태입니다: [설명]</span></span>
<span class="line"><span>지금 내가 Discover, Define, Develop, Deliver 중 어느 단계에 더 가까운지 판단해 주세요.</span></span>
<span class="line"><span>그리고 알려 주세요:</span></span>
<span class="line"><span>1. 내가 너무 일찍 다음 단계로 건너뛰었는지</span></span>
<span class="line"><span>2. 현재 단계에서 가장 보완해야 할 행동은 무엇인지</span></span>
<span class="line"><span>3. 지금 하지 말아야 할 일은 무엇인지</span></span></code></pre></div><p>이것은 초보자에게 특히 도움이 됩니다. 왜냐하면 &quot;문제를 아직 명확히 생각하지 않았는데 프로토타입을 그리기 시작하는&quot; 경우가 매우 흔하기 때문입니다.</p><h2 id="📚-과제" tabindex="-1">📚 과제 <a class="header-anchor" href="#📚-과제" aria-label="Permalink to “📚 과제”">​</a></h2><p>위 내용을 바탕으로 다음 과제를 완료해 주세요:</p><ol><li>최근에 만들고 싶은 제품 아이디어를 하나 골라, Discover, Define, Develop, Deliver 4단계의 초안을 작성하세요</li><li>Define 단계에서, 문제를 구체적인 한 문장으로 줄이도록 강제하세요</li><li>Develop 단계에서, 최소 3가지 다른 솔루션을 나열하고, 가장 먼저 떠오른 방법만 바라보지 마세요</li><li>Deliver 단계에서, 1주일 이내에 전달할 수 있는 최소 검증 버전을 하나 작성하세요</li></ol><h2 id="더-읽어볼-만한-자료" tabindex="-1">더 읽어볼 만한 자료 <a class="header-anchor" href="#더-읽어볼-만한-자료" aria-label="Permalink to “더 읽어볼 만한 자료”">​</a></h2><p>이 글은 주로 Design Council의 Double Diamond 공식 자료를 참고했습니다. 계속 읽어보세요:</p><ul><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/" target="_blank" rel="noreferrer">Design Council: The Double Diamond</a></li><li><a href="https://www.designcouncil.org.uk/our-work/skills-learning/tools-frameworks/framework-for-innovation-design-councils-evolved-double-diamond/" target="_blank" rel="noreferrer">Design Council: Framework for Innovation</a></li><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/history-of-the-double-diamond/" target="_blank" rel="noreferrer">Design Council: History of the Double Diamond</a></li></ul>`,171))])}}});export{g as __pageData,D as default};
